import React, { useState } from "react";

function App() {
  const [query, setQuery] = useState("");
  const [results, setResults] = useState([]);

  const handleSubmit = async () => {
    try {
      const res = await fetch("http://localhost:5000/api/query", {
        method: "POST",
        headers: {
          "Content-Type": "application/json"
        },
        body: JSON.stringify({ query })
      });

      const data = await res.json();

      setResults(data.publications || []);

    } catch (err) {
      console.error(err);
    }
  };

  return (
    <div style={styles.container}>
      <h1>AI Medical Research Assistant</h1>

      <div style={styles.searchBox}>
        <input
          type="text"
          placeholder="Ask medical research query..."
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          style={styles.input}
        />

        <button onClick={handleSubmit} style={styles.button}>
          Search
        </button>
      </div>

      <div style={styles.results}>
        {results.map((pub, index) => (
          <div key={index} style={styles.card}>
            <h3>{pub.title}</h3>
            <p>{pub.abstract || "No abstract available."}</p>
          </div>
        ))}
      </div>
    </div>
  );
}

const styles = {
  container: {
    padding: "40px",
    fontFamily: "Arial",
    background: "#f7f9fc",
    minHeight: "100vh"
  },

  searchBox: {
    display: "flex",
    gap: "10px",
    marginBottom: "30px"
  },

  input: {
    flex: 1,
    padding: "14px",
    fontSize: "16px"
  },

  button: {
    padding: "14px 24px",
    background: "#007bff",
    color: "white",
    border: "none",
    cursor: "pointer",
    borderRadius: "8px"
  },

  results: {
    display: "grid",
    gap: "20px"
  },

  card: {
    background: "white",
    padding: "20px",
    borderRadius: "12px",
    boxShadow: "0 4px 12px rgba(0,0,0,0.08)"
  }
};

export default App;
